table(['Metric','Measurement boundary'],[['Deployment','Contract submission through receipt; receipt gas and effective price'],['Upload','Encryption, signed request, both IPFS pins, ownership confirmation and owner-envelope persistence'],['Download','Signed request, read-audit confirmation, retrieval, integrity checks and decryption'],['Grant','Owner read/audit, unwrap/rewrap, grant confirmation and recipient-envelope persistence'],['Revoke','Submission through confirmation of permission deletion'],['Encryption / decryption','Complete shared cryptographic routine, including serialization/base64 and RSA work; excludes identity generation'],['Throughput','Successful confirmed createRecord transactions divided by measured workload duration'],['CPU / memory','Gateway+driver, EVM/API and two IPFS processes; no double counting of the gateway and driver'],['Network','Gateway and storage HTTP payload byte counters during five 1 MiB upload/download cycles']],[115,W-115])
sub('Equations and sampling')
add('<b>Transaction fee (ETH) = gasUsed x effectiveGasPriceWei / 10<super>18</super>.</b> Gas limit is the permitted upper bound; the receipt records actual consumption [4]. <b>TPS = confirmed successes / elapsed seconds.</b> Success rate equals confirmed successes divided by attempted operations. Latency equals completion time minus start time, using a monotonic clock.')
add('<b>CPU (%) = 100 x aggregate CPU seconds / elapsed wall seconds</b>, relative to one core; multiple processes can exceed 100%. Payload bandwidth in MiB/s equals measured bytes divided by 1,048,576 and elapsed seconds. Memory is RSS where available, otherwise measured peak RSS from getrusage. Sums of process peaks are upper bounds rather than simultaneous total RSS.')
add('File sizes are 1 KiB, 100 KiB and 1 MiB, with five repetitions each. Means, medians, nearest-rank p95, minimum and maximum are retained in JSON. There is no separate warm-up phase, so cold-start effects may be present. With only five repetitions, p95 equals the maximum and should be interpreted cautiously. Concurrent load scenarios jointly vary operation count and worker count; they are not a factorial experiment that isolates each factor.')

